raw:
{
  "spells": [
    {
      "id": "spell_fire_04",
      "theory": "驯灶术以魔力渗入燃料内部，使炭柴的燃烧面趋于均匀，并减缓火舌窜动。它不凭空生热，只让灶膛里已有的火焰更听话，燃料消耗因此降低一成。施术者需将魔力沿灶壁送入，与燃料接触后形成薄层约束，火候便不再忽大忽小。",
      "casting": "单膝跪在灶前，掌心距灶口一拃，用食指在空气中画一个向下的弧，同时缓缓吐出魔力，直到火焰由跳荡转为平稳。",
      "failure": "魔力送得太急时，火焰会突然缩成一小团，冒出呛人的白烟，随后又猛地窜起，燎焦灶边的干草。灶膛内壁若已开裂，约束层会从裂缝漏出，导致半边火旺半边火灭，锅底受热不均。",
      "counters": [
        "往灶膛撒一把湿盐，盐粒爆裂会打乱魔力约束层。",
        "用铁钩拨散燃料堆，破坏燃烧面的均匀分布。"
      ],
      "socialConsequences": "河谷里的农户常请会此术的人帮忙驯灶，省下的柴薪能多撑半月。卖炭的商贩不太喜欢它，却也会在炭价高时请人施术，以免主顾转用泥煤。乡约见证下，帮邻家驯灶可收一顿饭或几捆柴，但若把火候改得过大烧穿锅底，便要按约定赔偿。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "permit"
      },
      "proficiencyEffects": [
        "入门者只能稳住小火，添柴后需重新施术。",
        "百次练习后，可让中等火势保持半个时辰不跳。",
        "三百次以上，能凭手感判断何时该补魔力。",
        "六百次后，连湿柴也能烧得平稳，仍只省一成燃料。"
      ]
    },
    {
      "id": "spell_fire_05",
      "theory": "炭纹测温把魔力灌入一条炭粉画的细线，炭线会随所触器壁的温度改变颜色深浅。施术者通过触摸炭线末端，感知温差分布，无需直接用手试探灼热的锅壁。炭线必须紧贴金属或石面，悬空时魔力无法传导，读数也就失真。",
      "casting": "用指尖蘸炭粉，在器壁上画一条三寸长的线，末端留出米粒大的圆点。指腹按住圆点，默数三次呼吸，让魔力沿炭线铺开。",
      "failure": "炭线画得太粗时，颜色变化会混成一团，无法分辨细微温差。若器壁有油污，炭粉无法附着，魔力只在圆点处打转，指腹会感到一阵刺痛，却读不出任何温度。强行加大魔力，炭线会突然烧红，在器壁上留下焦痕。",
      "counters": [
        "用湿布擦掉炭线，魔力便失去传导路径。",
        "在器壁和炭线之间垫一片薄石，阻断接触。"
      ],
      "socialConsequences": "琥珀海岸的厨工和铁匠乐于用炭纹测温判断锅温或锻件火色，尤其在不能直接触碰时。卖测温石和羽毛温度计的人会抱怨生意被抢，但遇到贵重器皿仍推荐炭纹法，因为不伤表面。港务规定，若因误读温度导致货损，施术者需和船主一同接受问询，炭线残迹也须清理干净。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "consent"
      },
      "proficiencyEffects": [
        "初学时只能分辨烫与不烫，细温差需反复描线。",
        "熟练到百次，可读出器壁三处不同温度。",
        "三百次后，能在数息内完成画线与读温。",
        "六百次以上，隔着薄布也能大致判断，仍会受油污干扰。"
      ]
    },
    {
      "id": "spell_fire_06",
      "theory": "火线术把魔力压入地面，沿一条直线点燃细碎可燃物，形成两米长的低矮火墙。火焰高度不过膝，主要靠热浪和光亮阻挡行路，而非烧穿鞋底。地面须有干草、木屑或油渍等媒介，石板路上效果大减，雨中几乎无法维持。",
      "casting": "蹲身，以掌缘贴地，从身前向侧方划一道直线，同时将魔力灌入掌下。划到两米处收手，火线便沿划痕燃起。",
      "failure": "掌缘划得太快，魔力来不及渗入地面，火线会断成三四截，每截只烧几息就灭。若地面潮湿，火焰会缩成零星火星，冒出浓白烟，反而暴露位置。魔力灌得过多，火线会突然窜高，可能引燃旁边的干草堆，造成失控。",
      "counters": [
        "泼一桶水或湿沙，火线会立刻熄灭并冒白烟。",
        "用长棍横扫地面，把可燃物拨开，火线便无以为继。"
      ],
      "socialConsequences": "河谷的牧民在驱赶夜狼时偶尔使用火线术，但更多时候只用来圈住走失的牲畜。城中公会认为在街道施放火线属于危害公共安全，除非获得书面许可。琥珀海岸的仓库区严禁火线，违者按纵火未遂论处，船主和货主会联合要求赔偿，即使没有实际损失也要支付清理炭痕的费用。",
      "law": {
        "river": "consent",
        "city": "permit",
        "port": "crime"
      },
      "proficiencyEffects": [
        "初学火线只能维持十息，且常断成数截。",
        "百次练习后，可在干草上拉出完整两米火线。",
        "三百次以上，能控制火焰高度不过膝。",
        "六百次后，雨中也能勉强点燃，仍会迅速熄灭。"
      ]
    }
  ]
}
